<?php

declare(strict_types=1);

require_once dirname(__DIR__, 2) . '/config.php';
require_once ROOT_PATH . '/database/config/db.php';
require_once ROOT_PATH . '/security/middleware/AuthMiddleware.php';

AuthMiddleware::startSession();
$user = AuthMiddleware::requireAuth();
$csrf = AuthMiddleware::csrfToken();
$channelId = (int)($_GET['channel_id'] ?? 0);
$serverId = (int)($_GET['server_id'] ?? 0);
?>
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Collabs – <?= htmlspecialchars(APP_NAME, ENT_QUOTES, 'UTF-8') ?></title>
<style>
*{box-sizing:border-box}body{margin:0;background:#0f1117;color:#f5f7fb;font-family:Inter,system-ui,sans-serif}.shell{max-width:1180px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;gap:20px}.back{color:#aeb8ca;text-decoration:none}.layout{display:grid;grid-template-columns:310px 1fr;gap:20px;margin-top:24px}.panel{background:#171a23;border:1px solid #292e3b;border-radius:16px}.side{padding:16px}.main{padding:26px}.label{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#8e98aa}.server{margin:7px 0 20px;font-size:14px;color:#cbd3e0}.workspace{width:100%;border:0;background:transparent;color:#fff;text-align:left;padding:13px;border-radius:10px;cursor:pointer;margin:3px 0}.workspace:hover,.workspace.active{background:#232837}.workspace small{display:block;color:#8993a7;margin-top:5px}.btn{border:1px solid #363d4d;background:#202532;color:#fff;border-radius:9px;padding:10px 13px;cursor:pointer}.primary{background:#6d4aff;border-color:#6d4aff}.notice{padding:12px;border-radius:10px;background:#232837;color:#cbd3e0}.empty{text-align:center;padding:48px 20px;color:#9aa4b6}.title{display:flex;justify-content:space-between;gap:15px;align-items:flex-start}.title h1{margin:8px 0}.muted{color:#98a1b2}.pill{display:inline-flex;padding:5px 9px;border-radius:999px;background:#242a38;font-size:11px}.green{color:#8ee6a8}.cards{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:24px}.card{padding:17px;border:1px solid #2d3340;border-radius:12px;background:#141720}.card strong{display:block;margin-bottom:7px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.modal{position:fixed;inset:0;background:rgba(0,0,0,.72);display:none;align-items:center;justify-content:center;padding:20px}.form{width:min(520px,100%);background:#181c26;border:1px solid #333949;border-radius:16px;padding:22px}.form label{display:block;margin:12px 0 6px;color:#b8c0cf;font-size:13px}.form input,.form select{width:100%;background:#10131a;color:#fff;border:1px solid #363d4d;border-radius:8px;padding:10px}.choices{display:grid;grid-template-columns:1fr 1fr;gap:10px}.choice{padding:12px;border:1px solid #363d4d;border-radius:10px}.form-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}@media(max-width:800px){.layout,.cards,.choices{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="shell">
<header class="top"><div><a class="back" href="<?= BASE_URL ?>/modules/chat/chat.php<?= $channelId ? '?channel_id='.rawurlencode((string)$channelId) : '' ?>">← Back to Chat</a><h1>🤝 Collabs</h1><p class="muted">Server-wide collaboration. Documents and Whiteboard are shared independently from Chat channels.</p></div><span class="pill">👤 <?= htmlspecialchars((string)($user['full_name'] ?: $user['username']), ENT_QUOTES, 'UTF-8') ?></span></header>
<div class="layout">
<aside class="panel side"><div class="label">Server</div><div id="serverName" class="server">Loading server…</div><div class="label">Coworkspaces</div><div id="list"><div class="empty">Loading…</div></div><button class="btn primary" id="create">＋ Create Coworkspace</button></aside>
<main class="panel main" id="detail"><div class="empty"><h2>🤝 Server Collabs</h2><p>Every channel in the server can access the same Coworkspaces. Select one from the left.</p></div></main>
</div>
</div>
<div class="modal" id="modal"><form class="form" id="form"><h2>Create Coworkspace</h2><label>Name</label><input name="name" maxlength="200" placeholder="BSIT Capstone Project" required><label>Visibility</label><div class="choices"><label class="choice"><input type="radio" name="visibility" value="public" checked> <b>Public</b><br><span class="muted">Any member of this server can join.</span></label><label class="choice"><input type="radio" name="visibility" value="private"> <b>Private</b><br><span class="muted">Invitation or approved request required.</span></label></div><label><input type="checkbox" name="allow_create_documents" checked> Allow members to create documents</label><label><input type="checkbox" name="allow_edit_documents" checked> Allow members to edit documents</label><label><input type="checkbox" name="allow_whiteboard" checked> Allow members to use Whiteboard</label><label><input type="checkbox" name="allow_member_invites"> Allow members to invite others</label><div id="error" class="notice" style="display:none"></div><div class="form-actions"><button type="button" class="btn" id="cancel">Cancel</button><button class="btn primary">Create</button></div></form></div>
<script>
const API='<?= BASE_URL ?>/API/collaboration/server-coworkspaces.php',CSRF='<?= htmlspecialchars($csrf,ENT_QUOTES,'UTF-8') ?>',CHANNEL=<?= $channelId ?>,INITIAL_SERVER=<?= $serverId ?>,BASE='<?= BASE_URL ?>';
const state={server:null,workspaces:[],selected:null};
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function req(data={},method='GET'){const opt={method,headers:{'X-CSRF-Token':CSRF}};if(method!=='GET'){opt.headers['Content-Type']='application/json';opt.body=JSON.stringify({...data,csrf_token:CSRF})}const q=method==='GET'?'?'+new URLSearchParams(data):'';const r=await fetch(API+q,opt);const d=await r.json().catch(()=>({error:'Invalid server response'}));if(!r.ok||!d.success)throw new Error(d.error||'Request failed');return d}
async function boot(){try{const d=await req(INITIAL_SERVER?{server_id:INITIAL_SERVER}:{channel_id:CHANNEL});state.server=d.server;state.workspaces=d.workspaces||[];document.getElementById('serverName').textContent=state.server.name;renderList();const wanted=new URLSearchParams(location.search).get('workspace_id');if(wanted)select(Number(wanted))}catch(e){document.getElementById('serverName').textContent='Unable to load';document.getElementById('list').innerHTML='<div class="notice">'+esc(e.message)+'</div>'}}
function renderList(){const box=document.getElementById('list');box.innerHTML=state.workspaces.length?state.workspaces.map(w=>`<button class="workspace ${Number(w.id)===Number(state.selected)?'active':''}" data-id="${w.id}">${w.visibility==='private'?'🔒':'🟢'} ${esc(w.name)}<small>${w.active_count>0?'🟢 '+w.active_count+' active · ':''}${w.member_count} collaborators · ${w.member_role?esc(w.member_role):'Join'}</small></button>`).join(''):'<div class="empty">No Coworkspaces yet.</div>';box.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>select(Number(b.dataset.id)))}
async function select(id){state.selected=id;renderList();const w=state.workspaces.find(x=>Number(x.id)===id);if(!w)return;const joined=!!w.member_role;const host=String(w.member_role)==='host'||Number(w.host_id)===<?= (int)$user['id'] ?>;document.getElementById('detail').innerHTML=`<div class="title"><div><span class="pill">${w.visibility==='private'?'🔒 PRIVATE':'🟢 PUBLIC'}</span><h1>${esc(w.name)}</h1><p class="muted">Server-wide Coworkspace · ${w.member_count} collaborators · ${w.active_count||0} active now</p></div>${host?'<span class="pill">HOST</span>':''}</div><div class="cards"><div class="card"><strong>📄 Documents</strong><span class="muted">Word, Excel and PowerPoint documents shared by this Coworkspace.</span></div><div class="card"><strong>🖊 Whiteboard</strong><span class="muted">A dedicated collaborative Whiteboard independent from Chat channels.</span></div></div><div class="actions">${joined?'':'<button class="btn primary" id="join">'+(w.visibility==='private'?'Request Access':'Join Coworkspace')+'</button>'}<span class="pill">${w.member_role?('Your role: '+esc(w.member_role)):'Not a member'}</span></div>`;document.getElementById('join')?.addEventListener('click',async()=>{try{const action=w.visibility==='private'?'request_access':'join';await req({action,server_id:state.server.id,workspace_id:w.id},'POST');await boot();select(w.id)}catch(e){alert(e.message)}})}
document.getElementById('create').onclick=()=>document.getElementById('modal').style.display='flex';document.getElementById('cancel').onclick=()=>document.getElementById('modal').style.display='none';document.getElementById('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,err=document.getElementById('error');err.style.display='none';try{const d=await req({action:'create',server_id:state.server.id,channel_id:CHANNEL,name:f.name.value,visibility:f.visibility.value,allow_create_documents:f.allow_create_documents.checked,allow_edit_documents:f.allow_edit_documents.checked,allow_whiteboard:f.allow_whiteboard.checked,allow_member_invites:f.allow_member_invites.checked},'POST');document.getElementById('modal').style.display='none';location.href=BASE+'/modules/collaboration/server-coworkspaces.php?server_id='+state.server.id+'&workspace_id='+d.workspace.id}catch(e){err.textContent=e.message;err.style.display='block'}};
boot();
</script>
</body></html>
